```ts
import "dotenv/config";
import express from "express";
import { db } from "./db";
import bodyParser from "body-parser";

const app = express();
app.use(bodyParser.json());

const port = process.env.PORT || 3000;

// GET all companies (Read)
app.get("/companies", async (req: express.Request, res: express.Response) => {
  try {
    const companies = await db.selectFrom("companies").selectAll().execute();
    res.json(companies);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch companies" });
  }
});

// GET single company by ID (Read)
app.get("/companies/:id", async (req: express.Request, res: express.Response) => {
  try {
    const company = await db
      .selectFrom("companies")
      .selectAll()
      .where("id", "=", parseInt(req.params.id))
      .executeTakeFirst();

    if (!company) {
      return res.status(404).json({ error: "Company not found" });
    }

    res.json(company);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch company" });
  }
});

// POST new company (Create)
app.post("/companies", async (req: express.Request, res: express.Response) => {
  try {
    const newCompany = await db
      .insertInto("companies")
      .values(req.body)
      .returningAll()
      .executeTakeFirst();

    res.status(201).json(newCompany);
  } catch (error) {
    res.status(500).json({ error: "Failed to create company" });
  }
});

// PUT update company (Update)
app.put("/companies/:id", async (req: express.Request, res: express.Response) => {
  try {
    const updatedCompany = await db
      .updateTable("companies")
      .set(req.body)
      .where("id", "=", parseInt(req.params.id))
      .returningAll()
      .executeTakeFirst();

    if (!updatedCompany) {
      return res.status(404).json({ error: "Company not found" });
    }

    res.json(updatedCompany);
  } catch (error) {
    res.status(500).json({ error: "Failed to update company" });
  }
});

// DELETE company (Delete)
app.delete("/companies/:id", async (req: express.Request, res: express.Response) => {
  try {
    const deletedCompany = await db
      .deleteFrom("companies")
      .where("id", "=", parseInt(req.params.id))
      .returningAll()
      .executeTakeFirst();

    if (!deletedCompany) {
      return res.status(404).json({ error: "Company not found" });
    }

    res.json({ message: "Company deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete company" });
  }
});

app.listen(port, () => {
  console.log(`Example app listening on port ${port}`);
});
```

This implementation includes:

1. GET `/companies` - Fetch all companies
2. GET `/companies/:id` - Fetch a single company by ID
3. POST `/companies` - Create a new company
4. PUT `/companies/:id` - Update an existing company
5. DELETE `/companies/:id` - Delete a company

Features of this implementation:

- Error handling for all endpoints
- Appropriate HTTP status codes
- Response with JSON data
- Returns updated/created records using `returningAll()`
- 404 responses for not found resources
- Input through request body for POST and PUT
- ID parameter handling for single-resource operations

